-- 이 질의를 고쳐 qty가 NULL인 행까지 전체 행 수를 세세요.
-- COUNT(*)는 행을, COUNT(qty)는 qty에 값이 있는 행만 세요.
SELECT COUNT(*) AS n FROM stocks;

-- 이 질의를 고쳐 알려진 qty를 모두 더한 합계를 구하세요.
-- SUM과 AVG는 NULL을 빼고 계산해요. AVG의 분모도 값이 있는 행 수예요.
SELECT SUM(qty) AS amount FROM stocks;

-- 이 질의에 GROUP BY를 더해 분류별 합계를 한 행씩 내세요.
-- GROUP BY category는 분류가 같은 행끼리 묶어 묶음마다 SUM을 한 행씩 내요.
SELECT category, SUM(qty) AS n FROM stocks GROUP BY category ORDER BY category;

-- 이 질의에 HAVING을 더해 분류 합계가 5 이상인 분류만 남기세요.
-- HAVING은 묶은 뒤 그룹의 집계값에 거는 조건이에요.
SELECT category, SUM(qty) AS n FROM stocks GROUP BY category HAVING SUM(qty) >= 5 ORDER BY category;

-- 이 질의에 WHERE를 더해 qty가 3 이상인 행만 남긴 뒤 분류별로 더하세요.
-- WHERE는 묶기 전에 행을 걸러요. 남은 행만 묶여 더해져요.
SELECT category, SUM(qty) AS n FROM stocks WHERE qty >= 3 GROUP BY category ORDER BY category;

-- 이 질의를 고쳐 중복 없는 분류의 수를 세세요.
-- 집계 안의 DISTINCT는 같은 분류 값을 하나로 줄인 뒤 세요.
SELECT COUNT(DISTINCT category) AS n FROM stocks;

-- 이 순위 함수를 고쳐 같은 가격은 같은 순위, 그다음은 동점 수만큼 건너뛰게 하세요.
-- RANK는 동점에 같은 순위를 주고 다음 순위를 건너뛰어요. DENSE_RANK는 건너뛰지 않아요.
SELECT id, RANK() OVER(ORDER BY price DESC) AS r FROM stocks ORDER BY id;

-- 이 창에 PARTITION BY를 더해 분류마다 번호를 1부터 다시 매기세요.
-- PARTITION BY category는 분류마다 따로 창을 나눠요. 행은 지우지 않아요.
SELECT id, ROW_NUMBER() OVER(PARTITION BY category ORDER BY id) AS r FROM stocks ORDER BY id;

-- 이 창을 고쳐 ID 순서로 첫 행부터 지금 행까지의 누적 합을 보이세요.
-- 창 안의 ORDER BY와 ROWS 범위가 「처음부터 지금 행까지」를 정해요. NULL은 더하지 않아요.
SELECT id, SUM(qty) OVER(ORDER BY id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS n FROM stocks ORDER BY id;
